136	fn root_external_ok(argv: &[&str]) -> (String, Vec<String>, Vec<String>) {
137	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
138	    let Commands::External(tokens) = cli.command else {
139	        panic!(
140	            "expected root external subcommand for {argv:?}, got {:?}",
141	            cli.command
142	        );
143	    };
144	    assert!(
145	        !tokens.is_empty(),
146	        "external capture must always include the command name: {argv:?}"
147	    );
148	    (cli.config, cli.define, tokens)
149	}
150	
151	fn serve_external_ok(argv: &[&str]) -> (String, Vec<String>, Vec<String>) {
152	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
153	    let Commands::Serve(serve) = cli.command else {
154	        panic!("expected `serve` for {argv:?}, got {:?}", cli.command);
155	    };
156	    let ServeCommands::External(tokens) = serve.command else {
157	        panic!(
158	            "expected serve external subcommand for {argv:?}, got {:?}",
159	            serve.command
160	        );
161	    };
162	    assert!(
163	        !tokens.is_empty(),
164	        "external capture must always include the command name: {argv:?}"
165	    );
166	    (cli.config, cli.define, tokens)
167	}
168	
169	fn worker_ok(argv: &[&str]) -> (String, Vec<String>, WorkerArgs) {
170	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
171	    let Commands::Serve(serve) = cli.command else {
172	        panic!(
173	            "expected `serve worker` for {argv:?}, got {:?}",
174	            cli.command
175	        );
176	    };
177	    let ServeCommands::Worker(worker) = serve.command else {
178	        panic!("expected `worker` for {argv:?}, got {:?}", serve.command);
179	    };
180	    (cli.config, cli.define, worker)
181	}
182	
183	fn check_ok(argv: &[&str]) -> (String, Vec<String>, CheckArgs) {
184	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
185	    let Commands::Check(check) = cli.command else {
186	        panic!("expected `check` for {argv:?}, got {:?}", cli.command);
187	    };
188	    (cli.config, cli.define, check)
189	}
