215	// ---- declared subcommands take precedence over external capture ----------
216	
217	#[test]
218	fn declared_commands_are_not_swallowed_by_external_capture() {
219	    // Root-level declared names dispatch to the built-in commands.
220	    assert!(matches!(
221	        parse(&["tool", "check"]).unwrap().command,
222	        Commands::Check(_)
223	    ));
224	    assert!(matches!(
225	        parse(&["tool", "serve", "worker", "--port", "8080"])
226	            .unwrap()
227	            .command,
228	        Commands::Serve(ServeArgs {
229	            command: ServeCommands::Worker(_),
230	        })
231	    ));
232	
233	    // Prefixes and look-alikes at either level stay external.
234	    let (_, _, tokens) = root_external_ok(&["tool", "ser", "x"]);
235	    assert_eq!(tokens, vec!["ser", "x"]);
