    assert_eq!(tokens, vec!["--flag", "x", "--", ""]);

    // Declared names after the separator are plugin names, not commands.
    let (_, _, tokens) = root_external_ok(&["tool", "--", "serve", "x"]);
    assert_eq!(tokens, vec!["serve", "x"]);
